  'settings.reconnect.policyHint': 'अपने आप होने वाले री-कनेक्ट एक ही जगह से छोड़े जाते हैं, और वह जगह यह पन्ना नहीं है। एक तब शुरू होता है जब कोई डाउनलोड बैकएंड ख़ुद थोड़ी देर बाद एक और कोशिश माँगता है, और होस्ट इसी तरह कहता है कि सीमा इसी पते से बँधी है। कतार रुकी हो तो यह कभी नहीं चलता, क्योंकि राउटर रीबूट करने से वे डाउनलोड टूट जाते हैं जो अब भी चल रहे हैं। जब तक री-कनेक्ट पूरी तरह सेट न हो, तब तक भी यह कभी नहीं चलता। एक बार में एक ही चलता है: दूसरा अनुरोध राउटर के लिए झगड़ने के बजाय पहले का फ़ैसला देखता है। और अगर पता नहीं बदलता, तो कुछ भी जल्दी नहीं किया जाता और सामान्य पुनःप्रयास प्रतीक्षा अपने हिसाब से चलती रहती है।',

  'shell.bar': 'कतार और स्थिति पट्टी',
