  'settings.chunks': 'हर डाउनलोड पर कनेक्शन (0 = स्वतः)',
  'settings.chunksHint': 'जब कुछ और खास लागू न हो, तब एक डाउनलोड कितने कनेक्शन खोलता है। कोई नियम, या कोई एक डाउनलोड, अपनी संख्या बता सकता है और वह इस पर भारी पड़ती है। जो होस्टर कम ही सहता है उसे फिर भी कम ही मिलते हैं: होस्ट की सीमा संख्या को घटा ही सकती है, कभी बढ़ा नहीं सकती। 0 पर फैसला ऐप करता है। मुट्ठी भर से ज़्यादा कनेक्शन उस होस्टर पर कुछ नहीं देते जो प्रति फ़ाइल सीमा लगाता है, और खाते पर निशान लगवाने का पक्का तरीक़ा हैं।',
