  'props.name': 'नाम',
  'props.nameHint': 'एक फ़ाइल नाम, कभी कोई पथ नहीं: जो कुछ फ़ोल्डर लिखता है उसे काटकर एक ही नाम कर दिया जाता है। पूरा हो चुका डाउनलोड डिस्क पर भी नए नाम से हो जाता है, ताकि सूची और फ़ोल्डर आपस में उलट न पड़ें। जो चल रहा है वह अपने बैकएंड की खुली फ़ाइल पर टिका रहता है और खत्म होने पर नया नाम लेता है। जो शुरू ही नहीं हुआ वह तुरंत ले लेता है। नाम एक फ़ाइल का होता है, इसलिए यह खाना सिर्फ़ एक पंक्ति के लिए मिलता है।',
