  'props.priority': 'प्राथमिकता',
  'props.priorityHint': 'ऊँची पहले चलती है। यह उसी का क्रम बदलता है जो अभी इंतज़ार में है; जो डाउनलोड पहले से चल रहा है उसे कतार में वापस नहीं भेजा जाता।',
  'props.autoExtract': 'अभिलेख खोलें',
  'props.autoExtractHint': 'डाउनलोड पूरा होने पर आर्काइव खोला जाए या नहीं। „वंशानुगत“ यह निर्णय आर्काइव सेटिंग पृष्ठ पर छोड़ देता है, जो „बंद“ के बराबर नहीं है। स्विच खोलने के समय पढ़ा जाता है, इसलिए अभी चालू करने पर पहले पूरा हुआ कुछ भी खुल जाएगा।',
