  'settings.access.relay.body': 'रिले एक बिचौलिया है जो आपके सभी इंस्टेंस को घर के नेटवर्क के बाहर से, यानी कहीं से भी, पहुँच योग्य बनाता है। यह रिले प्रोजेक्ट मुफ़्त में देता है।',
  'settings.access.relay.use': 'परियोजना का रिले इस्तेमाल करें',
  'settings.access.relay.leadProject': 'बिना कुछ सेट किए चलता है। आपके इंस्टेंस आपस में जो कुछ कहते हैं वह सब एन्क्रिप्टेड है, और चाबी सिर्फ़ आपके पास है।',
