  'settings.access.ownRelay.containerHint': 'अगर आपका कोई भी इंस्टेंस बाहर से पहुँच योग्य नहीं है, तो रिले कहीं और होना चाहिए: आपके सर्वर पर या किसी छोटे VPS पर। कंटेनर को Unraid Community Applications से इंस्टॉल करें, या नीचे दिए कमांड से।\n\nकंटेनर को किसी सेटअप की ज़रूरत नहीं: चालू करें, ऊपर उसका पता डालें, बस। यह कुछ भी सहेजता नहीं, इसलिए बैकअप लेने को कुछ नहीं है।',
