  'settings.access.phrase.howStep1': 'इस इंस्टेंस पर "{button}" दबाएँ। बारह शब्द दिखाई देंगे।',
  'settings.access.phrase.howStep2': 'दूसरी मशीन पर KnightLoader खोलें, इसी पेज पर आएँ, "{button}" दबाएँ और बारह शब्द टाइप करें।',
  'settings.access.phrase.howStep3': 'हो गया! अब हर इंस्टेंस दूसरे के यहाँ „इंस्टेंस“ के नीचे दिखता है, और आप किसी को भी किसी से चला सकते हैं। रिले चालू होने पर आपके इंस्टेंस आपके नेटवर्क के बाहर से भी पहुँच योग्य हैं।',
  'settings.access.phrase.howWhat': 'ये शब्द एक रहस्य हैं, पता नहीं। हर इंस्टेंस इनसे दो चाबियाँ निकालता है: एक दूसरों को खोजने के लिए, एक एन्क्रिप्ट करने के लिए।\n\nएक-दूसरे को खोजने के लिए हर इंस्टेंस खुद इंटरनेट पर उसी मिलन-बिंदु को कॉल करता है। जो वही चाबी दिखाता है, उसे जोड़ दिया जाता है। इसलिए आपके किसी भी इंस्टेंस को बाहर से पहुँच योग्य होने की ज़रूरत नहीं।\n\nमिलन-बिंदु पढ़ नहीं सकता। वह आपके शब्द कभी नहीं देखता, और उससे गुज़रने वाला सब कुछ दूसरी चाबी से एन्क्रिप्टेड है।',
  'settings.access.phrase.statusDisconnected': 'जुड़ा नहीं',
  'settings.access.phrase.statusHintProject': 'प्रोजेक्ट रिले से जुड़ा है। रिमोट एक्सेस तैयार है।',
  'settings.access.phrase.statusHintOwn': 'आपके अपने रिले से जुड़ा है। रिमोट एक्सेस तैयार है।',
  'settings.access.phrase.statusHintOff': 'कोई रिले सक्रिय नहीं है। आपके इंस्टेंस केवल लोकल नेटवर्क में ही पहुँच योग्य हैं।',
  'settings.access.phrase.statusHintLost': 'रिले से संपर्क नहीं है। KnightLoader कोशिश करता रहता है। तब तक आपके इंस्टेंस केवल लोकल नेटवर्क में ही एक-दूसरे तक पहुँचते हैं।',
