  'settings.torrents.portMapUnconfirmed': 'राउटर ने अनुरोध स्वीकार कर लिया, लेकिन यह पुष्टि नहीं हो सकी कि मैपिंग वास्तव में काम कर रही है। कुछ राउटर यह चुपचाप करते हैं - नेटवर्क के बाहर से कनेक्टिविटी जाँच आज़माएँ।',
