  'settings.torrents.networkTitle': 'पीयर खोज',
  'settings.torrents.dht': 'DHT',
  'settings.torrents.dhtHint': 'बिना किसी ट्रैकर के, अन्य BitTorrent क्लाइंट को वितरित डायरेक्ट्री की तरह उपयोग करके पीयर ढूँढता है।',
  'settings.torrents.pex': 'पीयर एक्सचेंज (PEX)',
  'settings.torrents.pexHint': 'ज्ञात पीयर का पहले से जुड़े पीयर के साथ आदान-प्रदान करता है, ताकि कम पीयर वाला स्वार्म तेज़ी से मिल सके।',
  'settings.torrents.privateNote': 'एक निजी टॉरेंट अपना मेटाडेटा पता चलते ही दोनों को अपने आप बंद कर देता है, यहाँ की सेटिंग चाहे जो भी हो - अपलोड की गई .torrent फ़ाइल के लिए तुरंत, या मैग्नेट लिंक के अपने मेटाडेटा के स्वार्म से मिलते ही। ज़्यादातर निजी ट्रैकर इनमें से किसी का भी उपयोग करने वाले खातों को बैन कर देते हैं।',
  'settings.torrents.engineNote': 'लक्ष्य सीड अनुपात, लक्ष्य सीड अवधि और पोर्ट अब उस हर टॉरेंट तक पहुँचते हैं जिसे यह इंजन शुरू करता है - पोर्ट, हालाँकि, इस इंस्टेंस के आख़िरी रीस्टार्ट के बाद से सिर्फ़ बिल्कुल पहले टॉरेंट के लिए, क्योंकि इंजन का अपना टॉरेंट क्लाइंट केवल एक बार बनाया जाता है और उसके बाद कभी दोबारा नहीं बनाया जाता; बाद में की गई सेव फिर भी सही तरीक़े से सहेजी जाती है और अगले रीस्टार्ट से लागू होती है। अपलोड सीमा अब भी सिर्फ़ सहेजी और सत्यापित की जाती है, और इंजन के पास इसे किसी चल रहे डाउनलोड में लागू करने का अभी कोई ज़रिया नहीं है। नीचे दिए DHT और PEX की स्थिति एक सामान्य (ग़ैर-निजी) टॉरेंट के लिए भी वैसी ही है: इस इंस्टेंस का अपना डिफ़ॉल्ट भी अभी किसी चल रहे डाउनलोड तक नहीं पहुँचता, इसलिए यहाँ की सेटिंग चाहे जो भी हो, टॉरेंट दोनों को चालू रखते हुए सीड करना जारी रखता है - एक निजी टॉरेंट पूरी तरह अलग मामला है, नीचे दिया नोट देखें। फिर भी, नीचे दिया मैपिंग बटन कुछ वास्तविक करता है: यह ईमानदारी से राउटर से ऊपर दर्ज किए गए पोर्ट नंबर को फ़ॉरवर्ड करने का अनुरोध करता है, चाहे इस समय उस पर कोई टॉरेंट सुन रहा हो या नहीं।',
  'torrent.staging': 'जोड़ा जा रहा है…',
