  'onboarding.finish': 'KnightLoader का उपयोग शुरू करें',
  'onboarding.welcome.title': 'KnightLoader में आपका स्वागत है',
  'onboarding.welcome.body': 'KnightLoader एक सेल्फ़-होस्टेड डाउनलोड मैनेजर है: कोई लिंक चिपकाएँ या छोड़ें, और उसे वह बैकएंड ले लेता है जो असल में उसे संभालता है - सादे फ़ाइल लिंक के लिए बिल्ट-इन इंजन, मीडिया पेजों के लिए yt-dlp, जिन होस्टर के लिए आप पहले से भुगतान करते हैं उनके लिए डेब्रिड सेवा, या बाकी सब के लिए बिना इंटरफ़ेस वाला JDownloader। यह छोटा टूर उस एक सेटिंग को कवर करता है जिसे शुरू करने से पहले जाँचना उचित है।',
  'onboarding.welcome.langLabel': 'इंटरफ़ेस की भाषा',
  'onboarding.folder.title': 'फ़ाइलें कहाँ जानी चाहिए?',
  'onboarding.folder.body': 'यह वह फ़ोल्डर है जिसमें पूरे हो चुके डाउनलोड लिखे जाते हैं। कोई पथ टाइप करें या एक चुनने के लिए सर्वर ब्राउज़ करें - आप इसे जनरल सेटिंग्स पेज से कभी भी फिर बदल सकते हैं।',
  'onboarding.accounts.title': 'प्रीमियम होस्टर, जब भी आप चाहें',
  'onboarding.accounts.body': 'कतार बिना किसी खाते के भी काम करती है। जब आप किसी ऐसे होस्टर या डेब्रिड सेवा पर पूरी गति चाहें जिसके लिए आप पहले से भुगतान करते हैं, तो उसका लॉगिन खातों में जोड़ें - अभी यहाँ कुछ भी सेट करने की ज़रूरत नहीं है।',
  'onboarding.accounts.link': 'खाते खोलें',
  'onboarding.finished.title': 'आप तैयार हैं',
  'onboarding.finished.body': 'इसी के साथ टूर पूरा होता है। सेटिंग्स के अंदर सहायता पेज पर बाकी सब कुछ जो यह बिल्ड करता है उसका पूरा विवरण है, और ज़्यादातर नियंत्रणों के पीछे (i) आइकॉन में अपनी ख़ुद की व्याख्या होती है।',

