  'settings.nav.shortcuts': 'शॉर्टकट',
  'settings.shortcuts.subtitle': 'डिफ़ॉल्ट कीबोर्ड शॉर्टकट वाला हर कमांड, वहाँ के हिसाब से समूहीकृत जहाँ वह लागू होता है। कोई बाइंडिंग बदलें, या उसे उसके डिफ़ॉल्ट पर रीसेट करें।',
