  'settings.downloads.diskHint': 'तीन संख्याएँ जो डाउनलोड को डिस्क भरने के बाद नहीं, उससे पहले रोक देती हैं। तीनों का मतलब उस डिस्क के खाली बाइट हैं जिस पर डाउनलोड लिखा जा रहा है, इसलिए दूसरी डिस्क पर पड़ा कार्य फ़ोल्डर उसी पर नापा जाता है। शून्य उस संख्या को बंद कर देता है। यह क्या नहीं कर सकता: हर सिस्टम से यह नहीं पूछा जा सकता कि कितनी जगह खाली है, और जहाँ जवाब नहीं मिलता वहाँ कुछ भी कभी नहीं रोका जाता, क्योंकि जो पहरा न जानने पर रोक लगाए वह एक बिल्कुल स्वस्थ मशीन को रोक देता।',
