  'settings.feeds.seededHint': 'नई सदस्यता की पहली जाँच उस समय फ़ीड में जो कुछ है वह सब दर्ज कर लेती है और उसमें से कुछ भी नहीं जोड़ती, ताकि किसी प्रकाशक का पूरा पुराना ढेर एक साथ आपके पास न आ जाए। उसके बाद जो दिखता है वही जोड़ा जाता है।',
