  'settings.rules.action.category': 'श्रेणी',
  'settings.rules.action.categoryHint': 'मेल खाते लिंक को श्रेणियाँ पन्ने की किसी एक दराज़ में रख देता है, और वह दराज़ अपना फ़ोल्डर, कतार में अपनी जगह, अपना निकालने वाला स्विच और पहले से मौजूद फ़ाइल वाला अपना नियम साथ लाती है। अपरिवर्तित छोड़ने पर किसी नियम की इस बारे में कोई राय नहीं होती और लिंक बिना रखे रह जाता है। यही नियम अगर डाउनलोड फ़ोल्डर भी बताता है तो वही फ़ोल्डर जीतता है, और बाक़ी सब फिर भी दराज़ से आता है। मिटाई जा चुकी दराज़ का नाम देना सहेजते समय अस्वीकार हो जाता है, क्योंकि जो नियम ऐसी दराज़ की ओर इशारा करता है जो है ही नहीं, वह हर मेल खाते लिंक पर कुछ भी नहीं करता, बिना कुछ कहे।',
