  'disk.title': 'लक्ष्य फ़ोल्डर',
  'disk.hint': 'हर उस फ़ोल्डर पर खाली और भरी हुई जगह जिसमें कोई डाउनलोड उतर सकता है, और कतार को हर एक में अभी कितना और लिखना है। ये आँकड़े उसी पूछताछ से आते हैं जिसके सामने डिस्क की सीमाएँ जाँची जाती हैं, और ज़्यादा से ज़्यादा कुछ सेकंड पुराने होते हैं। खाली और भरी हुई जगह मिलकर हमेशा डिस्क का पूरा आकार नहीं बनतीं: फ़ाइल सिस्टम एक हिस्सा सिस्टम के लिए रोक रखता है, और प्रति उपयोगकर्ता कोटा इस इंस्टेंस को उससे कम दे सकता है जितना डिस्क पर सचमुच है। एक ही डिस्क पर पड़े दो फ़ोल्डर दोनों वही एक डिस्क दिखाते हैं, इसलिए पंक्तियों को कभी आपस में जोड़ें नहीं।',
  'disk.free': 'खाली',
  'disk.used': 'भरा हुआ',
  'disk.size': 'डिस्क का आकार',
  'disk.queued': 'अभी लिखा जाना है',
  'disk.queuedHint': 'जो डाउनलोड अभी बाक़ी हैं वे इस फ़ोल्डर में कितना और जोड़ेंगे: होस्ट का बताया हुआ आकार, घटा वह जो पहले ही आ चुका है। जिस डाउनलोड का आकार होस्ट नहीं बताता वह यहाँ शून्य गिना जाता है, इसलिए यह सबसे नीचे की सीमा है, कोई वादा नहीं, और इसीलिए डाउनलोड की पूरी क़तार के बगल में शून्य बाइट लिखा दिख सकता है। जो डाउनलोड आपने बंद कर रखे हैं वे इसमें नहीं आते, वही नियम जो सूची के नीचे की गिनतियाँ मानती हैं। जो डाउनलोड पहले से चल रहा है उसके लिए जगह आम तौर पर शुरू होते ही डिस्क पर अलग रख दी गई होती है, इसलिए उसके बाइट बगल वाली खाली जगह में से पहले ही घट चुके हैं और उसके ऊपर दोबारा नहीं जुड़ते।',
  'disk.tasks': '{n} डाउनलोड',
  'disk.unknown': 'यह सिस्टम खाली जगह नहीं बताता',
  'disk.unknownHint': 'हर कर्नेल से यह नहीं पूछा जा सकता कि डिस्क पर कितनी जगह बची है, और जिस कर्नेल पर यह चल रहा है उसके लिए इस बिल्ड के पास कोई पूछताछ नहीं है। जहाँ जवाब नहीं मिलता वहाँ कुछ भी नहीं रोका जाता: डाउनलोड ठीक वैसे ही शुरू होते हैं जैसे डिस्क की सीमाओं के आने से पहले होते थे। यह पंक्ति इसीलिए यहाँ है कि आप इसे सचमुच भरी हुई डिस्क से अलग पहचान सकें।',
  'disk.missing': 'अभी बना नहीं है',
  'disk.missingHint': 'यह फ़ोल्डर वही बनाता है जो उसमें पहली फ़ाइल लिखता है, इसलिए अभी यह है ही नहीं। आँकड़े {path} के बारे में हैं, उसके ऊपर का सबसे नज़दीकी फ़ोल्डर जो सचमुच मौजूद है, और वह उसी डिस्क पर है जिस पर डाउनलोड उतरता।',
  'disk.measured': '{path} पर नापा गया',
  'disk.elsewhereHint': 'फ़ोल्डर ख़ुद नापा नहीं जा सका, इसलिए उसके ऊपर का सबसे नज़दीकी फ़ोल्डर नापा गया जो नप सका। अगर कोई माउंट ऊपर नहीं आया, तो यह उस डिस्क से बिल्कुल अलग डिस्क हो सकती है जिसके लिए डाउनलोड बना है। संख्याओं से कुछ भी निकालने से पहले पथ देख लें।',
  'disk.sampled': '{n} सेकंड पहले पढ़ा गया',
  'disk.tight': 'कतार समाती नहीं',
  'disk.tightHint': 'इस फ़ोल्डर को उससे ज़्यादा देना है जितना डिस्क पर खाली है। यह पंक्ति अपने आप कुछ नहीं रोकती: डाउनलोड एक-एक करके तभी रोके जाते हैं जब उनकी बारी आती है, डाउनलोड सेटिंग्स पन्ने की संख्याओं के हिसाब से, और जिस डाउनलोड का आकार कोई नहीं जानता वह यहाँ गिना ही नहीं जाता।',
  'disk.truncated': 'हर फ़ोल्डर यहाँ नहीं है',
  'disk.truncatedHint': 'कतार तय किए गए फ़ोल्डरों के बाहर इतने फ़ोल्डरों की ओर जा रही है कि हर बार सबको नापना ठीक नहीं, इसलिए जिन्हें सबसे कम देना है वे छोड़ दिए गए। आपने जो फ़ोल्डर तय किए हैं वे हमेशा यहाँ रहते हैं।',
