  'settings.volume.title': 'डेटा की सीमा',
  'settings.volume.titleHint': 'इस इंस्टेंस ने जो डाउनलोड पूरे किए, वे आपकी तय की गई सीमा के सामने गिने जाते हैं, हर अवधि के लिए अलग। गिनती में हर पूरे डाउनलोड का वह आकार आता है जो होस्टर ने बताया था, इसलिए जो बिना आकार बताए पूरा हुआ वह शून्य गिना जाता है, और टॉरेंट जो अपलोड करता है वह गिना ही नहीं जाता। यह आपके डाउनलोड का हिसाब है, आपकी लाइन की माप नहीं: आपके राउटर ने असल में कितने बाइट इधर से उधर किए, यह यहाँ किसी को नहीं दिखता।',
  'settings.volume.cap': 'हर अवधि की सीमा (GB)',
  'settings.volume.capHint': '0 का मतलब कोई सीमा नहीं: गिनती चलती रहती है और कभी कुछ नहीं रोका जाता। यहाँ गीगाबाइट दशमलव में हैं, वैसे ही जैसे कोई प्रदाता अपना डेटा बताता है, इसलिए 500 GB यानी 500 000 000 000 बाइट, 465 GiB नहीं। इसी पन्ने पर ऊपर दिए डिस्क वाले मान द्विआधारी GiB में हैं, दूसरे सवाल के लिए दूसरी इकाई।',
  'settings.volume.resetDay': 'गिनती नए सिरे से शुरू होने का दिन',
  'settings.volume.resetDayHint': 'महीने का वह दिन जब गिनती फिर से शून्य से शुरू होती है, आम तौर पर वही दिन जब आपका डेटा नया मिलता है। जो महीना आपके चुने दिन से छोटा हो, उसमें वह उस महीने के आख़िरी दिन शुरू होती है और कभी अगले महीने में नहीं खिसकती। गिनती सर्वर की घड़ी से होती है, आपके ब्राउज़र की घड़ी से नहीं, क्योंकि कतार सर्वर ही रोकता है।',
  'settings.volume.action': 'सीमा पूरी होने पर',
  'settings.volume.actionHint': 'आप जो भी चुनें, पहले से चल रहा ट्रांसफ़र कभी नहीं तोड़ा जाता: फ़ाइल के बीच में रोकने का मतलब है वे बाइट फेंक देना जो आप पहले ही ख़र्च कर चुके हैं। “सिर्फ़ बता दें” कुछ नहीं बदलता, तब गिनती ही पूरी सुविधा है। “कोई नया डाउनलोड शुरू न करें” जो चल रहा है उसे पूरा होने देता है और गिनती के नए सिरे से शुरू होने तक कतार रोके रखता है, और हर प्रतीक्षा करती पंक्ति यही बताती है। “सब कुछ धीमा कर दें” कतार को चलती रहने देता है, नीचे दी गई गति पर।',
  'settings.volume.actionReport': 'सिर्फ़ बता दें',
  'settings.volume.actionPause': 'कोई नया डाउनलोड शुरू न करें',
  'settings.volume.actionThrottle': 'सब कुछ धीमा कर दें',
  'settings.volume.throttle': 'सीमा के बाद की गति (KiB/s)',
  'settings.volume.throttleHint': 'बची हुई अवधि के लिए यही गति लागू रहती है। यह आपकी बाक़ी सीमाओं के बगल में एक ऊपरी सीमा है, उनकी जगह कभी नहीं, इसलिए रात वाली खिड़की या शांत स्विच अगर इससे कम माँगें तो वही जीतते हैं। यहाँ 0 का मतलब होता कोई सीमा ही नहीं, यानी वही जो कोई सीमा न होने पर है, इसलिए सबसे छोटी काम की संख्या 1 है।',
  'settings.volume.noCap': 'कोई सीमा नहीं',
