  'failure.botCheck.hint': 'इंतज़ार करना, धीरे डाउनलोड करना या कोई दूसरी ब्राउज़र पहचान यहाँ कुछ नहीं बदलती। सिर्फ़ उस ब्राउज़र की कुकीज़ बदलती हैं जिसमें आप सचमुच साइन-इन हैं। उसी ब्राउज़र से साइट की cookies.txt निर्यात करें और यहाँ चिपका दें: वह एन्क्रिप्टेड क्रेडेंशियल भंडार में रहती है, yt-dlp को ऐसी फ़ाइल के रूप में सौंपी जाती है जिसे सिर्फ़ यही सर्वर पढ़ सकता है, और डाउनलोड ख़त्म होते ही मिटा दी जाती है।',
