  'failure.membersOnly.hint': 'yt-dlp वहाँ उसी के रूप में पहुँचता है जो सहेजी गई कुकीज़ कहती हैं। जिस खाते के पास सदस्यता है उससे साइन-इन करें, उसी ब्राउज़र से साइट की cookies.txt निर्यात करें और यहाँ चिपका दें। उस खाते पर सदस्यता न हो तो यहाँ कुछ भी जवाब नहीं बदलता।',
  'failure.membersOnly.action': 'इस साइट के लिए कुकीज़ सहेजें',
  'failure.geoBlocked.line': 'साइट यह वीडियो इस क्षेत्र में नहीं परोसती।',
  'failure.geoBlocked.hint': 'कुकीज़ से कुछ नहीं होगा: रोक पते पर है, खाते पर नहीं। KnightLoader किसी yt-dlp डाउनलोड को अपने किसी नामित कनेक्शन से भी नहीं भेज सकता, क्योंकि yt-dlp अपनी अलग प्रक्रिया के रूप में चलता है और अपना प्रॉक्सी उसी एनवायरनमेंट से लेता है जिसमें यह सर्वर शुरू हुआ था। इसलिए हल इस विंडो के बाहर है: सर्वर को किसी VPN के पीछे शुरू करें, या उसके लिए HTTP_PROXY और HTTPS_PROXY सेट करें।',
  'failure.gone.line': 'स्रोत कहता है कि यह अब वहाँ नहीं है।',
  'failure.gone.hint': 'स्रोत पर मिटा दिया गया, हटा दिया गया या निजी कर दिया गया। न कोई खाता इसे वापस लाता है और न कोई पुनः प्रयास, और हर अगली कोशिश होस्टर से बस वही जवाब दोबारा कहलवाती है। लिंक हटाने से पंक्ति सूची से निकल जाती है, जो पहले ही डाउनलोड हो चुका है वह डिस्क पर बना रहता है।',
  'failure.gone.action': 'यह लिंक हटाएँ',
  'failure.drm.line': 'यह वीडियो एन्क्रिप्टेड है, और yt-dlp इसे डिक्रिप्ट नहीं करता।',
  'failure.drm.hint': 'DRM ऐसी रोक नहीं है जिससे कोई लॉगिन या कोई दूसरा पता पार पा ले: डेटा गड्डमड्ड होकर आता है, और चाबी सिर्फ़ उसी प्लेयर तक जाती है जिस पर साइट भरोसा करती है। इसके लिए सेट करने को कुछ है ही नहीं। उसी लिंक की बाक़ी पंक्तियों पर, यानी थंबनेल, विवरण और सबटाइटल पर, इसका आम तौर पर कोई असर नहीं होता और वे रह सकती हैं।',
  'failure.drm.action': 'यह लिंक हटाएँ',
  'failure.extractorBroken.line': 'साइट बदल गई है, और इस बिल्ड का yt-dlp वीडियो अब बाहर नहीं निकाल पाता।',
  'failure.extractorBroken.hint': 'yt-dlp ने खुद यही कहा: वह पन्ना पढ़ नहीं सका और उसने बग रिपोर्ट माँगी। लगभग हमेशा साइट ने कुछ खिसका दिया होता है, और कुछ ही दिनों में नया yt-dlp उसे फिर से संभालने लगता है। yt-dlp KnightLoader इमेज के भीतर आता है, इसलिए नए yt-dlp तक का रास्ता एक नई इमेज है, यहाँ का कोई बटन नहीं: यह सर्वर उसे बदल नहीं सकता, और कंटेनर में उसके पास नई कॉपी रखने की जगह भी नहीं है।',
