  'idleAction.lastRunFailed': '{at} पर विफल।',
  'idleAction.problem.empty': 'कोई प्रोग्राम नहीं लिखा है, इसलिए चलने को कुछ नहीं। ऊपर प्रोग्राम का पूरा पथ भरें।',
  'idleAction.problem.notFound': '{program} इस इंस्टेंस पर मौजूद नहीं है।',
  'idleAction.problem.notFoundContainer': '{program} इस कंटेनर के भीतर मौजूद नहीं है। यहाँ सिर्फ़ वही है जो इमेज साथ लाती है: न systemd, न curl, न ssh, न sudo। कमांड को होस्ट पर रखें और यहाँ से उस तक पहुँचें, या यहाँ ऐसी स्क्रिप्ट की ओर इशारा करें जिसे आपने कंटेनर में माउंट किया है।',
  'idleAction.problem.notExecutable': '{path} वहाँ है, पर चलाया नहीं जा सकता। उस पर चलाने का अधिकार लगाएँ और देखें कि जिस उपयोक्ता के रूप में यह प्रक्रिया चलती है वह उसे पढ़ सके: कंटेनर में वह uid 1000 है, root नहीं।',
  'idleAction.problem.permission': 'सिस्टम ने मना कर दिया: इस प्रक्रिया को इसकी अनुमति नहीं है। कंटेनर में यह uid 1000 के रूप में चलती है, बिना root के और होस्ट तक बिना किसी पहुँच के, इसलिए जो कुछ भी मशीन की बिजली की स्थिति बदलता है, वह होस्ट पर ही होना चाहिए।',
  'idleAction.problem.timeout': 'प्रोग्राम {seconds} सेकंड बाद भी चल रहा था और रोक दिया गया। हो सकता है उसने अपना काम फिर भी कर दिया हो। अगर कमांड को ज़्यादा समय लेना चाहिए तो सीमा बढ़ा दें।',
  'idleAction.problem.exit': 'प्रोग्राम {code} कोड के साथ रुक गया। उसकी अपनी आउटपुट: {output}',
  'idleAction.problem.notSupported': 'यह बिल्ड वह नहीं कर सकता। कतार खत्म होने पर की जाने वाली कोई दूसरी कार्रवाई चुनें।',
  'idleAction.problem.suspendRefused': 'सिस्टम ने सुलाने से मना कर दिया। Linux पर आम तौर पर अधिकार प्रबंधक ऐसी पुष्टि चाहता है जो यह ऐप दे ही नहीं सकता: अपने उपयोक्ता के लिए सुलाने की अनुमति दें, या “कमांड चलाएँ” पर जाएँ और मशीन को अपनी किसी स्क्रिप्ट से सुला दें।',
  'idleAction.runFailed': 'कमांड शुरू ही नहीं हो सका।',
  'idleAction.failedTitle': 'कतार खत्म होने पर की जाने वाली कार्रवाई नहीं चली',
