  'idleAction.dismiss': 'छिपाएँ',
  'settings.transfer.title': 'सिर्फ़ सेटिंग्स',
  'settings.transfer.hint': 'settings.json को एक फ़ाइल में लिखता है: कतार की सीमाएँ, फ़ोल्डर, नियम-समूह, श्रेणियाँ और समय-सारणी। डाउनलोड सूची नहीं और इतिहास नहीं। फ़ाइल आपका ब्राउज़र सहेजता है, वह और कहीं नहीं जाती।',
  'settings.transfer.export': 'सेटिंग्स निर्यात करें',
