  'settings.transfer.withSecrets': 'सहेजे हुए पासवर्ड भी साथ ले जाएँ',
  'settings.transfer.withSecretsHint': 'चालू: फ़ाइल में राउटर का पासवर्ड, हर प्रॉक्सी पासवर्ड और हर आर्काइव पासवर्ड सादे पाठ में होता है। बंद: ये खाने दूसरी मशीन पर खाली पहुँचते हैं और आप उन्हें एक बार भर देते हैं। दोनों ही हालतों में कोई भेद ऐसी जगह पड़ा हो सकता है जिसे यहाँ कोई नहीं पहचानता: ऐसा फ़ीड पता जिसमें API कुंजी हो, या री-कनेक्ट स्क्रिप्ट में लिखा हुआ पासवर्ड।',
  'settings.transfer.notTravellingLabel': 'जो कभी साथ नहीं जाता',
  'settings.transfer.notTravelling': 'इस फ़ाइल में यह कभी नहीं होता: आपके debrid और होस्टर लॉगिन, हेडर प्रोफ़ाइल, कैप्चा कुंजियाँ, इस इंटरफ़ेस का लॉगिन पासवर्ड, और आपकी स्क्रिप्ट। वे settings.json के बाहर एन्क्रिप्टेड पड़े हैं, और पूरा संग्रह भी उन्हें साथ नहीं ले जाता। उन्हें नई मशीन पर आप दोबारा सेट करते हैं।',
