  'settings.eventTargets.droppedHint': 'जो झोंका इस लक्ष्य के लेने से तेज़ आता है, वह रखा नहीं जाता बल्कि गिरा दिया जाता है। रखने का मतलब होता ऐसी ख़बरों पर मेमोरी ख़र्च करना जो पहुँचने तक बासी हो चुकी हैं। अगर यह संख्या बढ़ती ही जाए, तो लक्ष्य उन घटनाओं के लिए बहुत धीमा है जो आपने चिह्नित की हैं।',
  'settings.eventTargets.problem.noUrl': 'इस पंक्ति में कोई पता नहीं है, इसलिए कुछ भेजा नहीं जा सकता। ऊपर एक भरें।',
  'settings.eventTargets.problem.badUrl': 'पता http या https पते के रूप में पढ़ा नहीं जा सकता। स्कीम और होस्ट जाँचें।',
  'settings.eventTargets.problem.badMethod': 'यह बिल्ड GET, POST और PUT भेजता है और कुछ नहीं। तीनों में से एक चुनें।',
  'settings.eventTargets.problem.badTemplate': 'कोई प्लेसहोल्डर बंद नहीं हुआ। हर एक नाम के दोनों ओर दो प्रतिशत चिह्नों के साथ लिखा जाता है।',
  'settings.eventTargets.problem.unknownTrigger': 'इस पंक्ति की कोई घटना ऐसी है जिसे यह बिल्ड चलाता ही नहीं। उसे हटाएँ और सूची में से कोई चुनें।',
  'settings.eventTargets.problem.dns': 'होस्ट इस इंस्टेंस के भीतर से हल नहीं हो सका। कंटेनर के पास अक्सर अपना ही नेम सर्वर होता है, इसलिए जिस पते तक आपका अपना कंप्यूटर पहुँचता है, वहाँ यह मशीन अपने आप नहीं पहुँच जाती।',
  'settings.eventTargets.problem.refused': 'वहाँ कुछ नहीं सुन रहा। पोर्ट जाँचें, और यह भी कि सेवा चल भी रही है या नहीं।',
  'settings.eventTargets.problem.tls': 'सर्टिफ़िकेट स्वीकार नहीं हुआ। आम तौर पर वजह आपके अपने सर्वर पर ख़ुद जारी किया गया सर्टिफ़िकेट होती है। अपने नेटवर्क में http लें, या इस कंटेनर को वह सर्टिफ़िकेट दे दें।',
  'settings.eventTargets.problem.timeout': 'दूसरे छोर ने समय सीमा के भीतर जवाब नहीं दिया। ऊपर सीमा बढ़ाएँ, या किसी तेज़ चीज़ पर भेजें।',
  'settings.eventTargets.problem.auth': 'दूसरे छोर ने प्रमाण ठुकरा दिए। हेडरों में टोकन जाँचें, और याद रखें कि किसी दूसरे होस्ट पर रीडायरेक्ट Authorization हेडर को रास्ते में गिरा देता है।',
  'settings.eventTargets.problem.notFound': 'दूसरे छोर पर वह पथ है ही नहीं। ntfy में विषय पते का हिस्सा होता है, Matrix में कमरे की पहचान।',
  'settings.eventTargets.problem.rejected': 'दूसरे छोर ने अनुरोध पढ़ा और ठुकरा दिया। नीचे का जवाब उसके अपने शब्दों में है और यहाँ की किसी भी इबारत से ज़्यादा बताता है।',
  'settings.eventTargets.problem.rateLimited': 'दूसरा छोर फ़िलहाल मना कर रहा है, क्योंकि एक साथ बहुत कुछ पहुँच गया। शोर करने वाली घटनाएँ हटा दें, या किसी सार्वजनिक सर्वर के बजाय अपने सर्वर पर भेजें।',
  'settings.eventTargets.problem.server': 'दूसरे छोर ने अपनी ही किसी त्रुटि के साथ जवाब दिया। जितनी बार यह पंक्ति इजाज़त देती है, उतनी बार दोहराया जा चुका है, इसलिए अब सबसे पहले उनके अपने लॉग में देखना चाहिए।',
  'settings.scripts.trigger.linkAdded': 'कोई लिंक जुड़ता है',
