  'settings.nav.health': 'स्थिति',
  'settings.module.metrics': 'किसी निगरानी के लिए मापों का पता',
  'settings.health.title': 'अभी की स्थिति',
  'settings.health.titleHint': 'यह पन्ना सिर्फ़ पढ़ता है। इस पर कुछ भी शुरू, बंद या बदलता नहीं, और इसे खुला छोड़ देने से भी कुछ नहीं बदलता। आँकड़े हर दस सेकंड में लाए जाते हैं; कोई लाना विफल हो तो पन्ना खाली होने के बजाय पिछली पढ़त वहीं टिकी रहती है। जिन हिस्सों को पूछना पड़ता है, वे आधे मिनट तक साझा किए जाते हैं, इसलिए यहाँ जो दिखता है वह डाउनलोड पन्ने की पंक्तियों से तीस सेकंड तक पीछे हो सकता है।',
  'settings.health.version': 'संस्करण',
  'settings.health.uptime': 'कब से चल रहा',
  'settings.health.uptimeHint': 'यह प्रक्रिया कितनी देर से चल रही है, मशीन कितनी देर से नहीं। जो कंटेनर एक घंटा पहले पुनः आरंभ हुआ है वह यहाँ फिर शून्य से शुरू होता है, होस्ट चाहे कुछ भी कहे। उसके बगल की तारीख़ सर्वर की अपनी घड़ी है, आपके ब्राउज़र की नहीं।',
  'settings.health.startedAt': 'शुरू हुआ',
  'settings.health.sampled': '{n} सेकंड पहले पढ़ा गया',
  'settings.health.loadFailed': 'स्थिति लोड नहीं हो सकी। क्या सर्वर उपलब्ध है?',
  'settings.health.oldHealthHint': 'पुराना पता /api/health नहीं बदला है और जब तक यह प्रक्रिया चलती है तब तक "ok" ही जवाब देता है, इस पन्ने पर चाहे कुछ भी लिखा हो। यह जान-बूझकर है: कंटेनर की अपनी हेल्थ जाँच, Click\'n\'Load पुल और फ़ोन ऐप की आपके नेटवर्क में इंस्टेंस ढूँढ़ने वाली खोज, तीनों उसे पढ़ती हैं, और वहाँ "ok" के अलावा कोई जवाब कंटेनर को बीमार बता देता और फ़ोन इस इंस्टेंस को ढूँढ़ना बंद कर देता। ख़राबी की ख़बर इसी पन्ने पर मिलती है; वह पता सिर्फ़ इतना कहता है कि कोई सुन भी रहा है या नहीं।',
