  'health.state.unknown': 'यहाँ जाँचा नहीं जा सकता',
  'settings.health.parts': 'घटक',
  'settings.health.partsHint': 'ऐप के हर उस घटक के लिए एक पंक्ति जो अपने आप ख़राब हो सकता है। जिस घटक को आपने इस इंस्टेंस पर कभी सेट ही नहीं किया, वह यही कहता है और ख़राबी में नहीं गिना जाता, और जिस घटक के बारे में यह बिल्ड पूछ ही नहीं सकता, वह भी यही कहता है, जो एक तीसरा जवाब है और कोई चुपचाप रखा शून्य नहीं। किसी पंक्ति को पढ़ने से कुछ नहीं बदलता: जो घटक कहता है कि वह नहीं चल रहा, वह पहले से कुछ देर से ख़राब है, यहाँ आपको बस पता चलता है।',
