  'health.part.relay': 'रिले',
  'health.part.captcha': 'कैप्चा',
  'health.remedy.store.failed': 'डेटाबेस ने जवाब नहीं दिया। डाउनलोड चलते रहते हैं, पर उनके बारे में अब कुछ लिखा नहीं जा रहा, इसलिए पुनः आरंभ उस सबको खो देगा जो तब से बदला है। देखें कि डेटा फ़ोल्डर अब भी माउंट है और अब भी लिखने लायक़ है।',
  'health.remedy.jd.unreachable': 'KL_JD ऐसा पता बताता है जहाँ यह इंस्टेंस अभी नहीं पहुँच पा रहा। देखें कि JDownloader कंटेनर चल रहा है और उसका API पोर्ट यहाँ से जवाब देता है। जो लिंक सिर्फ़ JDownloader ला सकता है, वे तब तक कतार में रहते हैं; वे विफल नहीं हुए हैं।',
  'health.remedy.jd.notWired': 'JDownloader फिर से जवाब दे रहा है, पर इस प्रक्रिया ने अपने बैकएंड शुरू होते समय जोड़े थे और तब वह उसके पास नहीं था। KnightLoader को पुनः आरंभ करें, ताकि वह ले लिया जाए।',
  'health.remedy.ytdlp.missing': 'इस प्रक्रिया के शुरू होते समय कोई yt-dlp नहीं मिला (KL_YTDLP, या PATH पर "yt-dlp")। तब मीडिया पन्ने वेरिएंट में खुलने के बजाय साइट की अपनी त्रुटि के साथ विफल होते हैं। उसे मिलने के लिए पुनः आरंभ चाहिए।',
  'health.remedy.disk.low': 'कोई गंतव्य फ़ोल्डर उस सीमा से नीचे है जो आपने डाउनलोड पन्ने पर लगाई है। जब तक वहाँ फिर जगह न हो, या जब तक आप सीमा घटा न दें, वहाँ कुछ नया शुरू नहीं होता। जो पहले से चल रहा है उसे यह सीमा नहीं रोकती।',
  'health.remedy.disk.elsewhere': 'कोई फ़ोल्डर वहाँ है ही नहीं, इसलिए ये आँकड़े उसके ऊपर वाले सबसे पास के फ़ोल्डर के हैं। अगर कोई माउंट ऊपर नहीं आया, तो यह बिल्कुल दूसरी डिस्क है। संख्याओं पर भरोसा करने से पहले पथ देख लें।',
  'health.remedy.accounts.benched': 'कम से कम एक होस्टर खाते को किसी ख़राबी के बाद अकेला छोड़ा जा रहा है। प्रतीक्षा पूरी होने पर उसे अपने आप एक बार और आज़माया जाता है, और प्रतीक्षा हर बार दोगुनी हो जाती है। अभी जानना हो तो खाते पन्ने पर जाएँ और उस पंक्ति पर ताज़ा करें दबाएँ।',
  'health.remedy.accounts.invalid': 'कम से कम एक होस्टर खाता ठुकरा दिया गया। नई कुंजी या नया कराया गया सब्सक्रिप्शन इसे ठीक करता है, इंतज़ार नहीं।',
