  'health.remedy.relay.down': 'रिले का पता सहेजा है और कनेक्शन नहीं बना। यह इंस्टेंस अपने आप कोशिश करता रहता है और स्थानीय तौर पर सब कुछ हमेशा की तरह चलता है; सिर्फ़ बाहर से उस तक पहुँचना नहीं चलता।',
  'health.remedy.captcha.waiting': 'कोई बैकएंड रुककर किसी इंसान से पूछ रहा है। जब तक कोई जवाब न दे, उसके पीछे कुछ नहीं हिलता।',
  'settings.health.tasks': 'अभी के डाउनलोड',
  'settings.health.tasksHint': 'सूची की अभी की एक झलक, समय के साथ की गिनती नहीं। “विफल” उन पंक्तियों को गिनता है जो त्रुटि लिए हुए सूची में पड़ी हैं, इसलिए यह संख्या तब घटती है जब आप उन्हें हटाते हैं और जब सूची आपके तय किए दिनों के बाद साफ़ की जाती है, और तब फिर बढ़ती है जब कुछ नया बिगड़ता है। यहाँ कुछ भी दर नहीं है, और यहाँ कुछ भी यह नहीं बताता कि कुछ कितनी बार विफल हुआ है।',
