  'settings.health.scrapeSwitch': 'मेट्रिक्स पते पर जवाब दें',
  'settings.health.scrapeHint': 'एक दूसरा पता खोलता है जो वही आँकड़े सादे पाठ के रूप में देता है, उसी रूप में जिसे Prometheus और उसके बाद बने औज़ार पढ़ते हैं। इसे लाया जाता है, भेजा कभी नहीं: इस मशीन से कुछ भी बाहर नहीं जाता, जब तक आपकी अपनी निगरानी यहाँ आकर उसे न माँगे। जब तक यह बंद है, वह पता है ही नहीं और 404 जवाब देता है, ठीक वैसे ही जैसे कोई भी दूसरा पता जो इस ऐप के पास नहीं है। पासवर्ड वाले इंस्टेंस पर उसे लाने के लिए आपका कोई एक API टोकन चाहिए, और यह हर संग्रह करने वाले को सिखाया जा सकता है। संग्रह करने वाला कोई Origin हेडर नहीं भेजता, इसलिए वह पार निकल जाता है; किसी दूसरे पते पर खुला ब्राउज़र टैब एक भेजता है और तब ठुकरा दिया जाता है जब वह इस इंस्टेंस के अपने पते से मेल नहीं खाता। उस पाठ में आपके गंतव्य फ़ोल्डरों के पथ होते हैं, इसलिए उसे वहीं दें जहाँ आप फ़ोल्डरों के नाम खुद भी देते।',
