  'settings.owner.noOwners': 'इस सिस्टम पर फ़ाइलों का कोई मालिक होता ही नहीं, इसलिए तुलना करने को कुछ नहीं है। यह कोई ख़राबी नहीं है।',
  'settings.owner.checkTitle': 'फ़ोल्डर जाँच',
