  'settings.owner.v.ok': 'फ़ाइलें यहाँ {fileOwner} के रूप में {fileMode} के साथ उतरती हैं, नए उपफ़ोल्डर {subdirMode} के साथ, और फ़ोल्डर खुद {dirOwner} का है। इसमें कुछ भी खटकने वाला नहीं।',
  'settings.owner.v.ownerMismatch': 'फ़ाइलें यहाँ {fileOwner} के रूप में उतरती हैं, पर फ़ोल्डर {dirOwner} का है। पढ़ना अक्सर फिर भी चलता है; किसी दूसरे खाते से उनका नाम बदलना, उन्हें खिसकाना और मिटाना नहीं चलता, और जो कुछ यह मानकर चलता है कि फ़ोल्डर अपने ही सामान का मालिक है, वह इन फ़ाइलों को पराया समझता है।',
  'settings.owner.v.groupUnreadable': 'फ़ाइलें यहाँ {fileMode} के साथ उतरती हैं, इसलिए उन्हें सिर्फ़ {fileOwner} खोल सकता है। किसी दूसरे खाते के नीचे चलने वाले को नाम दिखते हैं और उसके आगे कुछ नहीं मिलता।',
  'settings.owner.v.dirUnreadable': 'नए उपफ़ोल्डर यहाँ {subdirMode} के साथ बनते हैं। उनके भीतर {fileOwner} के अलावा कोई नहीं पहुँचता, उनमें पड़ी फ़ाइलें चाहे कुछ भी होने दें, और हर डाउनलोड ऐसे ही किसी फ़ोल्डर में उतरता है।',
  'settings.owner.v.notWritable': 'यह इंस्टेंस यहाँ बिल्कुल भी नहीं लिख सकता: {detail}',
  'settings.owner.v.missing': 'यह फ़ोल्डर वहाँ है ही नहीं। जब पहली बार उसमें कुछ लिखा जाएगा, तब वह बना दिया जाएगा।',
  'settings.owner.v.unknown': 'इस सिस्टम पर फ़ाइलों का कोई मालिक होता ही नहीं, इसलिए यहाँ तुलना करने को कुछ नहीं है। यह कोई ख़राबी नहीं है।',
  'settings.owner.fix.user': 'कंटेनर को उसी खाते के नीचे शुरू करें जिसका यह फ़ोल्डर है: रन कमांड में --user {dirUid}:{dirGid}। Unraid पर यह Extra Parameters में जाता है।',
  'settings.owner.fix.chown': 'या इसके बदले फ़ोल्डर ही सौंप दें, होस्ट पर: chown -R {uid}:{gid} {dir}',
  'settings.owner.fix.mask': 'इसमें यह इंस्टेंस कुछ नहीं बदल सकता। मास्क वहाँ से आता है जिसने कंटेनर शुरू किया, और माउंट किया हुआ शेयर umask, file_mode या dir_mode विकल्प से अपना मास्क थोप सकता है। इसे वहीं ठीक करें जहाँ फ़ोल्डर माउंट होता है।',
  'settings.owner.fix.recreate': 'बदले हुए रन कमांड के लिए कंटेनर नए सिरे से बनाना पड़ता है। पुनः आरंभ काफ़ी नहीं: पहचान उसी क्षण तय हो जाती है जब वह शुरू होता है।',
  'settings.owner.fix.past': 'जो फ़ाइलें पहले से डाउनलोड हो चुकी हैं, उनका मालिक वही रहता है जिसके साथ वे लिखी गई थीं। आप जो बदलते हैं वह आगे आने वाली चीज़ों पर लागू होता है; बाक़ी के लिए ऊपर वाला कमांड चाहिए।',
  'settings.selftest.title': 'स्व-जाँच',
  'settings.selftest.hint': 'जो कुछ यह इंस्टेंस अपने बारे में पता कर सकता है: JDownloader साइडकार, yt-dlp, आपके फ़ोल्डर, आपके debrid लॉगिन, रिले और घड़ी। यह सब इसी मशीन पर चलता है। इसमें से सिर्फ़ debrid लॉगिन बाहर जाते हैं, उन प्रदाताओं तक जिन्हें आपने सेट किया है।',
  'settings.selftest.run': 'स्व-जाँच चलाएँ',
  'settings.selftest.running': 'जाँचा जा रहा…',
  'settings.selftest.pending': 'इंतज़ार में',
  'settings.selftest.never': 'अभी तक नहीं चली।',
  'settings.selftest.lastRun': 'आख़िरी बार {when} चली।',
  'settings.selftest.startFailed': 'स्व-जाँच शुरू नहीं की जा सकी: {error}',
